#include<stdio.h>
#include<math.h>
#include<vector>
#include<algorithm>
using namespace std;
#include<stdlib.h>
float median(vector<float> l){
    long n = l.size();
    std::vector<long> minHeap;
    std::vector<long> maxHeap;
    maxHeap.push_back(l[0]);
    if(n == 1)
        return l[0];
    for(long i = 1; i < n; i++) {
        if(l[i] <= maxHeap[0]) {
            maxHeap.push_back(l[i]);
            std::push_heap(maxHeap.begin(), maxHeap.end(), std::greater<long>());
        }
        else {
            minHeap.push_back(l[i]);
            std::push_heap(minHeap.begin(), minHeap.end());
        }
        if(maxHeap.size() > minHeap.size() + 1) {
            std::pop_heap(maxHeap.begin(), maxHeap.end(), std::greater<long>());
            minHeap.push_back(maxHeap.back());
            std::push_heap(minHeap.begin(), minHeap.end());
            maxHeap.pop_back();
        }
        else if(minHeap.size() > maxHeap.size()) {
            std::pop_heap(minHeap.begin(), minHeap.end());
            maxHeap.push_back(minHeap.back());
            std::push_heap(maxHeap.begin(), maxHeap.end(), std::greater<long>());
            minHeap.pop_back();
        }
    }
    if(maxHeap.size() == minHeap.size())
        return (maxHeap[0] + minHeap[0]) / 2.0;
    else
        return maxHeap[0];
}

