#include<stdio.h>
#include<math.h>
#include<string>
#include<map>
using namespace std;
#include<algorithm>
#include<stdlib.h>
string sort_numbers(string numbers){
    if (numbers.empty()) return "";
    std::map<std::string, int> myMap = {
        {"zero", 0},
        {"one", 1},
        {"two", 2},
        {"three", 3},
        {"four", 4},
        {"five", 5},
        {"six", 6},
        {"seven", 7},
        {"eight", 8},
        {"nine", 9}
    };
    std::vector<int> allValues;
    std::stringstream ss(numbers);
    std::string token;
    while (ss >> token) {
        allValues.push_back(myMap[token]);
    }
    std::sort(allValues.begin(), allValues.end());
    std::vector<std::string> allStrings;
    for (auto itr = allValues.begin(); itr != allValues.end(); ++itr) {
        allStrings.push_back(myMap.find(*itr)->first);
    }
    std::string result = "";
    for (auto itr = allStrings.begin(); itr != allStrings.end(); ++itr) {
        result += *itr + " ";
    }
    return result.substr(0, result.size() - 1);
}

