#include<stdio.h>
#include<math.h>
#include<string>
#include<map>
using namespace std;
#include<algorithm>
#include<stdlib.h>
string sort_numbers(string numbers){
    std::map<std::string, int> numeric_values = {
    {"zero", 0},
    {"one", 1},
    {"two", 2},
    {"three", 3},
    {"four", 4},
    {"five", 5},
    {"six", 6},
    {"seven", 7},
    {"eight", 8},
    {"nine", 9}
  };
  // split numbers into a vector of strings
  std::vector<std::string> unsorted_numbers;
  std::stringstream ss(numbers);
  std::string numeral;
  while (ss >> numeral) {
    unsorted_numbers.push_back(numeral);
  }
  // convert vector of numeral strings to vector of ints
  std::vector<int> numbers_to_sort;
  for (int i = 0; i < unsorted_numbers.size(); i++) {
    numbers_to_sort.push_back(numeric_values[unsorted_numbers[i]]);
  }
  // sort the vector of ints
  std::sort(numbers_to_sort.begin(), numbers_to_sort.end());
  // convert the vector of ints back to a vector of numeral strings
  for (int i = 0; i < numbers_to_sort.size(); i++) {
    for (std::map<std::string, int>::iterator it = numeric_values.begin(); it != numeric_values.end(); it++) {
      if (it->second == numbers_to_sort[i]) {
        unsorted_numbers[i] = it->first;
      }
    }
  }
  // create the output string
  std::string output;
  for (int i = 0; i < unsorted_numbers.size(); i++) {
    output += unsorted_numbers[i];
    if (i < unsorted_numbers.size() - 1) {
      output += " ";
    }
  }
  return output;
}

