int max_fill(vector<vector<int>> grid,int capacity){
    std::priority_queue<long> cells;
    // Fill each row with 0
    for (long row = 0; row < grid.size(); row++) {
        long count = 0;
        for (long col = 0; col < grid[row].size(); col++) {
            if (grid[row][col] == 1) {
                count++;
            }
        }
        if (count > 0) {
            cells.push(count);
        }
    }
    long total_fill = 0;
    while (cells.size() > 0) {
        long top = cells.top();
        cells.pop();
        long fill = std::min(top, capacity);
        if (fill > 0) {
            total_fill += fill;
        }
        if (top > capacity) {
            top -= capacity;
            cells.push(top);
        }
    }
    return total_fill;
}

