        for(long j = 0; j < grid[i].size(); j++) {
            // Set water to 0.
            long water = 0;
            // For each row below,
            for(long k = i; k < grid.size(); k++) {
                // Add the cell's value to water.
                water += grid[k][j];
                // If the cell's value is 1,
                if(grid[k][j] == 1) {
                    // Move to the next row.
                    break;
                }
            }
            // If water is less than capacity,
            if(water < capacity) {
                // Set water to 0.
                water = 0;
                // For each row above,
                for(long k = i; k >= 0; k--) {
                    // Add the cell's value to water.
                    water += grid[k][j];
                    // If the cell's value is 1,
                    if(grid[k][j] == 1) {
                        // Move to the next row.
                        break;
                    }
                }
            }
            // If water is greater than max_water,
            if(water > max_water) {
                // Set max_water to water.
                max_water = water;
            }
        }
    }
    // Return max_water.
    return max_water;
}

