    for(long h = 0; h < row; h++) {
        long pass = 0;
        for(long c = 0; c < col; c++) {
            if(h < heights[c]) {
                ans++;
                pass++;
            }
        }
        if(pass == capacity) {
            break;
        }
    }
    return ans;
}

