#include<stdio.h>
#include<math.h>
#include<vector>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int smallest_change(vector<int> arr){
    std::vector<long> left(arr.size());
    left[0] = arr[0];
    for (int i = 1; i < arr.size(); i++) {
        left[i] = arr[i] + left[i - 1];
    }
    std::vector<long> right(arr.size());
    right[arr.size() - 1] = arr[arr.size() - 1];
    for (int i = arr.size() - 2; i >= 0; i--) {
        right[i] = arr[i] + right[i + 1];
    }
    long min = std::numeric_limits<long>::max();
    for (int i = 0; i < arr.size(); i++) {
        long left_sum, right_sum;
        if (i == 0) {
            left_sum = 0;
        } else {
            left_sum = left[i - 1];
        }
        if (i == arr.size() - 1) {
            right_sum = 0;
        } else {
            right_sum = right[i + 1];
        }
        if (left_sum + right_sum < min) {
            min = left_sum + right_sum;
        }
    }
    return min;
}

