    int len = s.length();
	for (int i = 0; i < len; i++) {
		// subtract number of letters in the alphabet to normalize indexes
		s[i] -= 26;
		// shift down by one letter
		s[i] += 1;
		// shift down by two letters
		s[i] += 2;
		// shift down by another two letters
		s[i] += 2;
		// normalize indexes again
		s[i] += 26;
	}
	return s;
}

