int vowels_count(string s){
    long count = 0;
    for (std::string::iterator it = s.begin(); it != s.end(); ++it) {
        switch (std::tolower(*it)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                count++;
                break;
            case 'y':
                if (it == s.end() - 1) {
                    count++;
                }
                break;
            default:
                break;
        }
    }
    return count;
}

