    for (int j = 0; j < sizeof(vowels) / sizeof(vowels[0]); j++) {
      if (tolower(s[i]) == vowels[j]) {
        count++;
      }
    }
  }
  if (last_element == 'y') {
    count++;
  }
  return count;
}

