vector<int> sum_product(vector<int> numbers){
    //a = sum, b = product
	long a = 0, b = 1;
	if (numbers.size() == 0) {
		a = 0;
		b = 1;
	}
	else {
		for (int i = 0; i < numbers.size(); i++) {
			a += numbers[i];
			b *= numbers[i];
		}
	}
	return std::make_tuple(a, b);
}

