#include<stdlib.h>
bool will_it_fly(vector<int> q,int w){
    std::vector<long> r;
	r = q;
	std::reverse(r.begin(), r.end());
	long sum = 0;
	for (auto i : q)
		sum += i;
	return ((q == r) && (sum <= w));
}

