#include<stdio.h>
#include<math.h>
#include<string>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int digitSum(string s){
    // Check if string is empty
	if (s.empty()) {
		return 0;
	}
	// Make result a double because if it is an int it would go out of scope
	double result = 0;
	// Iterate through the string and check if the character is uppercase
	for (int i = 0; i < s.length(); i++) {
		// If it is uppercase add the value to the result
		if (isupper(s[i])) {
			result += s[i];
		}
	}
	// Cast the result back to an int because there is no need for the extra
	// decimals
	return (int)result;
}

