#include<math.h>
#include<vector>
#include<algorithm>
using namespace std;
#include<stdlib.h>
int prod_signs(vector<int> arr){
    if (arr.empty()) {
    return std::nullopt;
  }
  int sign = 0;
  long product = 1;
  long sum = 0;
  for (auto elem : arr) {
    sign = std::signbit(elem) ? -1 : 1;
    if (sign == 0) {
      product = product * 0;
    } else {
      product = product * sign;
    }
    sum = sum + std::abs(elem);
  }
  return product * sum;
}

