#include<algorithm>
using namespace std;
#include<stdlib.h>
int prod_signs(vector<int> arr){
    if (arr.empty()) {
    return std::nullopt;
  }

  int sign_multiply = 1;
  int sum_magnitude = 0;
  for (long & number : arr) {
    if (number == 0) {
      continue;
    }
    sign_multiply *= number / std::abs(number);
    sum_magnitude += std::abs(number);
  }
  return sign_multiply * sum_magnitude;
}

