    std::vector<int> binary_repr;
    int carry = 0;
    int sum = 0;
    while(N) {
        sum = N % 2 + carry;
        carry = 0;
        if(sum > 1) {
            sum = sum % 2;
            carry = 1;
        }
        binary_repr.push_back(sum);
        N = N / 2;
    }
    if(carry == 1) {
        binary_repr.push_back(carry);
    }
    int i = binary_repr.size() - 1;
    while(i >= 0) {
        result += std::to_string(binary_repr[i]);
        i--;
    }
    return result;
}

