vector<int> maximum(vector<int> arr,int k){
    std::vector<long> result;
    std::priority_queue<long> pq;
    for (auto num : arr) {
        pq.push(num);
        if (pq.size() > k) {
            pq.pop();
        }
    }
    while (!pq.empty()) {
        result.push_back(pq.top());
        pq.pop();
    }
    return result;
}

