    std::priority_queue<long> q;
    for (long i = 0; i < k - 1; i++)
        q.push(arr[i]);
    // extract the max and insert
    for (long i = k - 1; i < n; i++) {
        q.push(arr[i]);
        result[i - k + 1] = q.top();
        q.pop();
