    // we found an opening bracket
    if (ch == '<') {
      stack.push(ch);
    }
    // we found a closing bracket
    else {
      // if we found a closing bracket but there are no
      // opening brackets we have a wrong bracketing
      if (stack.empty()) {
        return false;
