vector<int> sort_third(vector<int> l){
    // 1. Get the index of the third element in the list
  // 2. Create a new vector of the same size as l
  // 3. Fill in the values of the new vector in the first two indicies
  // 4. Sort the third set of elements and fill in the new vector
  // 5. Return the new vector
  std::vector<long> ret;
  long third = l.size() / 3;
  long part = third * 2;
  std::sort(l.begin() + third, l.begin() + part);
  for (long i = 0; i < l.size(); i++) {
    if (i % 3 == 0) {
      ret.push_back(l[i]);
    }
  }
  for (long i = 0; i < third; i++) {
    ret.push_back(l[i + third]);
  }
  for (long i = part; i < l.size(); i++) {
    ret.push_back(l[i]);
  }
  return ret;
}

