int how_many_times(string str,string substring){
    //if length of string is less than length of substring, just return 0
    if(string.length() < substring.length())
        return 0;
    //else if length of string is equal to length of substring, just return 1 if they are same or 0 if they are not same
    else if(string.length() == substring.length())
        return (string == substring);
    //else if length of string is greater than length of substring, then iterate the characters of string
    else{
        long count = 0;
        std::string::iterator i, j;
        for(i = string.begin(); i < string.end(); i++){
            j = i;
            std::string::iterator k = substring.begin();
            while(*j == *k && k < substring.end()){
                ++j;
                ++k;
            }
            if(k == substring.end())
                count++;
        }
        return count;
    }
}

