bool check_dict_case(map<string,string> dict){
    // Create a upper case and lower case set.
    std::set<std::string> uppercase;
    std::set<std::string> lowercase;
    std::set<std::string> keys = dict.keys();
    // Populate uppercase and lowercase set.
    for (std::string key : keys) {
        // If the key is present in either of the sets, return false.
        if (uppercase.find(key) != uppercase.end() || lowercase.find(key) != lowercase.end())
            return false;
        // If the key is neither in upper nor lower case set, add the key.
        uppercase.insert(key);
        lowercase.insert(key);
    }
    // If the dict is empty, return false.
    if (keys.size() == 0)
        return false;
    return true;
}

