using namespace std;
#include<algorithm>
#include<stdlib.h>
vector<float> rescale_to_unit(vector<float> numbers){ 
    if (numbers.size() < 2) {
		throw std::domain_error("rescale_to_unit requires at least two numbers");
	}
	float max_val = -std::numeric_limits<float>::infinity();
	float min_val = std::numeric_limits<float>::infinity();
	for (float number : numbers) {
		if (number > max_val) {
			max_val = number;
		}
		if (number < min_val) {
			min_val = number;
		}
	}
	float diff = max_val - min_val;
	if (diff == 0) {
		throw std::domain_error("all numbers are equal in rescale_to_unit");
	}
	std::vector<float> scaled;
	for (float number : numbers) {
		scaled.push_back((number - min_val) / diff);
	}
	return scaled;
}

