    std::sort(numbers.begin(), numbers.end());
    auto smallest = std::make_tuple(numbers[0], numbers[1]);
    auto distance = std::abs(std::get<0>(smallest) - std::get<1>(smallest));
    for (unsigned int i = 1; i < numbers.size() - 1; i++) {
        if (distance > std::abs(numbers[i] - numbers[i + 1])) {
            distance = std::abs(numbers[i] - numbers[i + 1]);
            smallest = std::make_tuple(numbers[i], numbers[i + 1]);
        }
    }
    return smallest;
}

