#include<stdio.h>
#include<math.h>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int starts_one_ends(int n){
    // For example,
    // count = 4, since the 4-digit numbers that start or end with 1 are:
    // 1000, 1001, 1002, 1100, 1101, 1102, 1110, 1111, 1112, 1120, 1121, 1122,
    // 1200, 1201, 1202, 1210, 1211, 1212, 1220, 1221, 1222, 2000, 2001, 2002,
    // 2100, 2101, 2102, 2110, 2111, 2112, 2120, 2121, 2122, 2200, 2201, 2202,
    // 2210, 2211, 2212, 2220, 2221, 2222.
    if (n == 1) return 2;
    // n >= 2
    // Let dp[i] be the count of the numbers of i-digit positive integers that
    // start or end with 1.
    //
    // If i is odd, the count is dp[i-1] * 2 + 3 * 2^(i/2-1) = dp[i-1] * 2 +
    // 2^i-1 - 2^(i/2).
    //
    // If i is even, the count is dp[i-1] * 2 + 2^(i/2).
    //
    // Therefore, the count of the numbers of n-digit positive integers that
    // start or end with 1,
    // is dp[n] = dp[n-1] * 2 + 2^(n/2) + 2^(n-1) - 2^(n/2-1).
    long dp[n+1];
    dp[1] = 2;
    dp[2] = 5;
    for (long i = 3; i <= n; ++i) {
        dp[i] = dp[i-1] * 2 + (1L << (i/2)) + (1L << (i-1)) - (1L << (i/2-1));
    }
    return dp[n];
}

