    switch(digitCount){
      case 0:
        if(digit==4){
          result.insert(0,"iv");
        }else if(digit==9){
          result.insert(0,"ix");
        }else{
          int i=0;
          while(i<digit){
            if(i==5){
              result.insert(0,"v");
