          while(i<digit){
            if(i==5){
              result.insert(0,"l");
            }else{
              result.insert(0,"x");
            }
            i++;
          }
        }
        break;
      case 2:
        if(digit==4){
          result.insert(0,"cd");
        }else if(digit==9){
          result.insert(0,"cm");
        }else{
          int i=0;
          while(i<digit){
            if(i==5){
              result.insert(0,"d");
            }else{
              result.insert(0,"c");
            }
