string int_to_mini_romank(int number){
    std::vector<int> numbers;
    std::vector<std::string> letters;
    for (int i = 1; i <= 1000; i *= 10) {
        numbers.push_back(i);
        letters.push_back(std::to_string(i));
    }
    for (int i = 0; i < numbers.size(); i++) {
        int digit = number / numbers[i];
        if (digit != 0) {
            if (digit == 9)
                return letters[i] + letters[i + 1];
            else if (digit >= 5)
                return letters[i] + std::string(digit - 5, letters[i][0]);
            else if (digit == 4)
                return letters[i] + letters[i];
            else
                return std::string(digit, letters[i][0]);
        }
        number %= numbers[i];
    }
    return "";
}

