using namespace std;
#include<algorithm>
#include<stdlib.h>
string rounded_avg(int n,int m){
    if (n > m) {
        return -1;
    }
    long sum = 0;
    for (long i = n; i <= m; i++) {
        sum += i;
    }
    long result = std::round(sum / (m - n + 1));
    return std::bitset<20>(result).to_string();
}

