		for (int j = i+1; j < numbers.size(); j++) {
			difference = numbers[i] - numbers[j];
			if (difference < 0) {
				difference = -difference;
			}
			if (difference > max_difference) {
				max_difference = difference;
			}
		}
	}
	return max_difference < threshold;
}

