using namespace std;
#include<stdlib.h>
string anti_shuffle(string s){
    int i = 0;
    std::string res = "";
    while(i < s.length()) {
        if(s[i] == ' ') {
            res += ' ';
            i++;
            continue;
        }
        if(i != s.length() - 1 && s[i + 1] == ' ') {
            res += s[i];
            i++;
            continue;
        }
        int start = i;
        while(i < s.length() && s[i] != ' ') {
            i++;
        }
        std::string temp = s.substr(start, i - start);
        std::sort(temp.begin(), temp.end());
        res += temp;
    }
    return res;
}

