using namespace std;
#include<algorithm>
#include<math.h>
#include<stdlib.h>
string words_in_sentence(string sentence){
    std::string result;
    std::stringstream ss;
    ss.str(sentence);
    std::string word;
    while (ss >> word) {
        auto len = word.length();
        bool is_prime = true;
        for (int i = 2; i <= std::sqrt(len); ++i) {
            if (len % i == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            result += word + " ";
        }
    }
    if (!result.empty()) {
        result.pop_back();
    }
    return result;
}

