        break;
     }
   }
   auto search = result;
   for (; search != word.rend(); ++search) {
     if (!vowels.count(*search)) {
        break;
     }
   }
   if (search == word.rend()) {
      return "";
   }
   auto result_distance = std::distance(result, word.rend());
   auto search_distance = std::distance(search, word.rend());
   if (result_distance - search_distance == 1) {
      return "";
   }
   return std::string(1, *result);
}

