string get_closest_vowel(string word){
    std::string vowels = "aeiou";
    std::string answer = "";
    std::vector<std::pair<int, int>> v;

    for (auto i = 0; i < word.size(); i++) {
        for (auto j = 0; j < vowels.size(); j++) {
            if (word[i] == vowels[j]) {
                v.push_back(std::make_pair(i, j));
            }
        }
    }

    for (auto i = 0; i < v.size(); i++) {
        auto left = std::find_if(word.begin(), word.begin() + v[i].first, [](auto &c) {
            return !(c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u');
        });
        auto right = std::find_if(word.begin() + v[i].first + 1, word.end(), [](auto &c) {
            return !(c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u');
        });
        if (left != word.begin() + v[i].first && right != word.end()) {
            return vowels.substr(v[i].second, 1);
        }
    }

    return answer;
}

