string decimal_to_binary(int decimal){
    // Given a decimal number, this program returns a string
    // with the number converted to binary
    // the string has a couple of extra characters at the beginning and at the end
    // to help with the formatting
    std::string final_string = "db";
    long dividend;
    long remainder;
    std::string temp;
    std::string bin_number;
    dividend = decimal;
    while (dividend != 0) {
        remainder = dividend % 2;
        temp = std::to_string(remainder);
        bin_number.append(temp);
        dividend = dividend / 2;
    }
    // we now have to reverse the bin_number
    // otherwise, it would be the binary representation of the decimal
    // number from the left to the right, not from the right to the left
    std::reverse(bin_number.begin(), bin_number.end());
    final_string.append(bin_number);
    final_string.append("db");
    return final_string;
}

