#include<stdlib.h>
int modp(int n,int p){
    if (n <= 1) {
        return n;
    }
    if (n % 2 == 0) {
        return (long) pow(modp(n / 2, p), 2) % p;
    }
    return (long) (modp(n - 1, p) * n) % p;
}

