long long minSubArraySum(vector<long long> nums){
    // Initialize the size of the vector
  int size = nums.size();
  // Initialize minimum sum to the first element of the array
  long min_sum = nums[0];
  // Initialize the sum of current sub-array to the first element of the array
  long curr_sum = nums[0];
  // Check if the number of elements in the array is less than or equal to 1
  if (size <= 1) {
    // If the size of the array is less than or equal to 1, then the minimum sum
    // is the first element in the array
    return min_sum;
  }
  // Loop from the second element in the array to the last element in the array
  for (int i = 1; i < size; i++) {
    // Check if the sum of the current sub-array is less than or equal to the
    // current element in the array
    if (curr_sum <= nums[i]) {
      // If the sum of the current sub-array is less than or equal to the current
      // element in the array, then set the sum of the current sub-array to the
      // current element in the array
      curr_sum = nums[i];
    } else {
      // If the sum of the current sub-array is greater than the current element
      // in the array, then add the current element in the array to the sum of
      // the current sub-array
      curr_sum += nums[i];
    }
    // Check if the sum of the current sub-array is less than the minimum sum
    if (curr_sum < min_sum) {
      // If the sum of the current sub-array is less than the minimum sum, then
      // set the minimum sum to the sum of the current sub-array
      min_sum = curr_sum;
    }
  }
  // Return the minimum sum
  return min_sum;
}

