vector<int> strange_sort_list(vector<int> lst){
    std::vector<long> result;
  long n = lst.size();
  if (n == 0) {
    return result;
  }
  if (n == 1) {
    result.push_back(lst[0]);
    return result;
  }
  bool asc = true;
  while (n > 0) {
    if (asc) {
      auto it = std::min_element(lst.begin(), lst.end());
      result.push_back(*it);
      lst.erase(it);
      asc = false;
    } else {
      auto it = std::max_element(lst.begin(), lst.end());
      result.push_back(*it);
      lst.erase(it);
      asc = true;
    }
    n = lst.size();
  }
  return result;
}

