vector<int> strange_sort_list(vector<int> lst){
    std::vector<long> result;
    // if the list length is less than 2 or
    // the list is a list of identical elements,
    // return the same list.
    if (lst.size() < 2 || std::all_of(lst.begin(), lst.end(), [lst](int i) { return i == lst[0]; }))
        return lst;
    // while the list is not empty
    while (!lst.empty()) {
        // identify the min and max value of the remaining list
        long min = *std::min_element(lst.begin(), lst.end());
        long max = *std::max_element(lst.begin(), lst.end());
        // add the min value to the result
        result.push_back(min);
        // remove the min value from the list
        lst.erase(std::remove(lst.begin(), lst.end(), min), lst.end());
        // if the list is empty, exit the loop
        if (lst.empty())
            break;
        // add the max value to the result
        result.push_back(max);
        // remove the max value from the list
        lst.erase(std::remove(lst.begin(), lst.end(), max), lst.end());
    }
    return result;
}

