int get_matrix_triples(int n){
    if(n < 3) return 0;
    long rem1 = 0, rem2 = 0;
    for(long i = 1; i <= n; i++) {
        if(i % 3 == 1) rem1++;
        else if(i % 3 == 2) rem2++;
    }
    long k = std::min(rem1, rem2);
    rem1 -= k;
    rem2 -= k;
    return rem1*rem2 + k*(k - 1)/2;
}

