int add_elements(vector<int> arr,int k){
    std::vector<long> dp(arr.size(), 0);
    long res = 0;
    for (int i = 0; i < k; i++) {
        if (arr[i] < 10) {
            res += arr[i];
        } else if (arr[i] < 100) {
            res += arr[i] - 10;
        } else {
            res += arr[i] - 100;
        }
    }
    dp[k-1] = res;
    for (int i = k; i < arr.size(); i++) {
        if (arr[i-k] < 10) {
            res -= arr[i-k];
        } else if (arr[i-k] < 100) {
            res -= arr[i-k] - 10;
        } else {
            res -= arr[i-k] - 100;
        }
        if (arr[i] < 10) {
            res += arr[i];
        } else if (arr[i] < 100) {
            res += arr[i] - 10;
        } else {
            res += arr[i] - 100;
        }
        dp[i] = res;
    }
    return dp[arr.size()-1];
}

