#include<stdio.h>
#include<math.h>
#include<vector>
#include<string>
using namespace std;
#include<algorithm>
#include<stdlib.h>
vector<string> words_string(string s){
    int len = s.length();
    std::vector<std::string> res;
    for(int i = 0; i < len; i++) {
        if(s[i] == ' ') {
            continue;
        }
        std::string temp = "";
        while(i < len && s[i] != ' ' && s[i] != ',') {
            temp += s[i];
            i++;
        }
        res.push_back(temp);
    }
    return res;
}

