vector<string> words_string(string s){
    std::vector<std::string> result;
  int pos = 0;
  for (int i = 0; i < s.size(); i++) {
    if (s[i] == ' ' || s[i] == ',') {
      if (pos < i) {
        result.push_back(s.substr(pos, i - pos));
      }
      pos = i + 1;
    }
  }
  if (pos < s.size()) {
    result.push_back(s.substr(pos, s.size() - pos));
  }
  return result;
}

