#include<math.h>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int prime_fib(int n){
    assert(n >= 1);
	long a = 2, b = 3, c = 5;
	if (n == 1) return a;
	if (n == 2) return b;
	if (n == 3) return c;

	for (int i = 4; i <= n; i++) {
		long f = a + b + c;
		a = b;
		b = c;
		c = f;

		while (!is_prime(c)) {
			f = a + b + c;
			a = b;
			b = c;
			c = f;
		}
	}
	return c;
}

