#include<stdio.h>
#include<math.h>
#include<algorithm>
using namespace std;
#include<stdlib.h>
bool is_equal_to_sum_even(int n){
    std::set<int> answer;
    answer.insert(n);
    std::vector<int> v;
    for(int i = 2; i < n; i++) {
        if(n % i == 0) {
            v.push_back(i);
        }
    }
    for(int i = 0; i < v.size(); i++) {
        for(int j = i; j < v.size(); j++) {
            for(int k = j; k < v.size(); k++) {
                if(n % (v[i] + v[j] + v[k]) == 0) {
                    answer.insert(v[i] + v[j] + v[k]);
                }
            }
        }
    }
    return answer.size() == 4;
}

