		else if (music_string[i] == '|') {
			beat.push_back(music_string[i]);
		}
		else {
			counter++;
		}
	}
	counter = (counter + 1) / 2;
	//Parsing note

	for (int i = 0; i < note.size(); i++) {
		if (note[i] == 'o') {
			note_beat.push_back(4);
		}
		else if (note[i] == '.') {
			note_beat.push_back(1);
		}
	}
	//Parsing beat

	for (int i = 0; i < beat.size(); i++) {
		if (beat[i] == '|') {
			it = note_beat.begin();
			note_beat.insert(it + i, *(it + i) / 2);
			note_beat.erase(it + i + 1);
		}
	}
	//Parsing counter

	if (counter > 0) {
		it = note_beat.begin();
		note_beat.insert(it, counter);
	}
	return note_beat;
}

