string file_name_check(string file_name){
    // 1. Check the file name if it has not more than 3 digits
    int counter = 0;
    for (auto &c : file_name) {
        if (c >= '0' && c <= '9') {
            counter++;
        }
    }
    if (counter > 3) {
        return "No";
    }
    // 2. Check file name if it contains exactly one dot '.'
    int dot_counter = 0;
    for (auto &c : file_name) {
        if (c == '.') {
            dot_counter++;
        }
    }
    if (dot_counter != 1) {
        return "No";
    }
    // 3. Check the file name if it starts with a letter from a latin alphapet
    if (file_name[0] < 'a' || file_name[0] > 'z') {
        if (file_name[0] < 'A' || file_name[0] > 'Z') {
            return "No";
        }
    }
    // 4. Check the file name if the substring after the dot is one of these ['txt', 'exe', 'dll']
    std::string file_type = file_name.substr(file_name.length() - 3, 3);
    if (file_type != "txt" && file_type != "exe" && file_type != "dll") {
        return "No";
    }
    return "Yes";
}

