bool right_angle_triangle(float a,float b,float c){
    // c^2 = a^2 + b^2
    // sort a, b, c such that c is largest
    if (a > b) {
        std::swap(a, b);
    }
    if (b > c) {
        std::swap(b, c);
    }
    if (a > b) {
        std::swap(a, b);
    }
    return std::pow(c, 2) == std::pow(a, 2) + std::pow(b, 2);
}

