bool right_angle_triangle(float a,float b,float c){
    std::vector<long> sides = {a, b, c};
    std::sort(sides.begin(), sides.end());
    if (sides[0] <= 0 || sides[2] >= sides[0] + sides[1]) {
        return false;
    }
    long maxSide = sides[2];
    long minSide = sides[0];
    long otherSide = sides[1];
    return pow(maxSide, 2) == pow(minSide, 2) + pow(otherSide, 2);
}

