#include<math.h>
#include<vector>
#include<string>
#include<algorithm>
using namespace std;
#include<stdlib.h>
int count_distinct_characters(string str){ 
    // Initialize the number of distinct characters
    long count = 0;
    // For each character in the string
    for (int i = 0; i < string.length(); i++) {
        // For each character up to the current character
        bool flag = true;
        for (int j = 0; j < i; j++) {
            // If they are the same
            if (string[i] == string[j]) {
                // Flag that the current character is not distinct
                flag = false;
                break;
            }
        }
        // If it is still flagged as a distinct character
        if (flag) {
            // Increase the number of distinct characters
            count++;
        }
    }
    // Return the number of distinct characters
    return count;
}

