#include<string>
#include<algorithm>
using namespace std;
#include<stdlib.h>
int count_distinct_characters(string str){ 
    int res = 0;
    int len = string.length();
    int freq[256] = {0};
    for(int i = 0; i < len; i++) {
        if(!freq[tolower(string[i])]) {
            res++;
            freq[tolower(string[i])]++;
        }
    }
    return res;
}

