vector<int> even_odd_palindrome(int n){
    std::tuple<long, long> retval{0, 0};
    if (n > 1000) {
        n = 1000;
    }
    std::vector<int> counts(10, 0);
    int max_digits = 0;
    while (n > 0) {
        int d = n % 10;
        counts[d]++;
        n /= 10;
        max_digits++;
    }
    for (int d = 0; d < 10; d++) {
        for (int i = 0; i < counts[d]; i++) {
            if (d % 2 == 0) {
                std::get<0>(retval)++;
            } else {
                std::get<1>(retval)++;
            }
        }
    }
    // Let's also consider a single digit as a palindrome.
    std::get<0>(retval)++;
    // If the number has an even number of digits, then we will have a middle digit which
    // we can choose anything.
    if (max_digits % 2 == 0) {
        // From the remaining counts, we have n choices to choose the middle element.
        long possibilities = 1;
        for (int d = 0; d < 10; d++) {
            if (counts[d] > 0) {
                possibilities *= counts[d];
            }
        }
        std::get<0>(retval) += possibilities;
        std::get<1>(retval) += possibilities;
    }
    return retval;
}

