    return {};
  }
  std::vector<long> result(numbers.size() * 2 - 1);
  std::copy(numbers.begin(), numbers.end(), result.begin());
  auto next = numbers.end();
  auto current = numbers.end() - 1;
  while (current != numbers.begin()) {
    result[2 * (current - numbers.begin()) - 1] = delimeter;
    current--;
  }
  return result;
}

