vector<int> rolling_max(vector<int> numbers){
    std::vector<long> output(numbers.size());
    std::deque<long> aux;
    for (int i = 0; i < numbers.size(); i++) {
        // firstly, remove old elements from the queue
        while (!aux.empty() && aux.front() <= i - numbers.size()) {
            aux.pop_front();
        }
        // now, we keep only elements which are bigger or equal than numbers[i]
        while (!aux.empty() && numbers[aux.back()] <= numbers[i]) {
            aux.pop_back();
        }
        // insert the current element
        aux.push_back(i);
        // get the maximum element at this moment
        output[i] = numbers[aux.front()];
    }
    return output;
}

