#include<stdlib.h>
int largest_prime_factor(int n){
    // Check for base cases
    if (n == 1 || n == 2) {
        return n;
    }
    // Check if n is even
    if (n % 2 == 0) {
        return largest_prime_factor(n / 2);
    }
    // All other cases are odd
    for (long i = 3; i <= sqrt(n); i+=2) {
        if (n % i == 0) {
            return largest_prime_factor(n / i);
        }
    }
    // Case where n is prime
