    for (auto i : lst) {
        std::vector<long> divisors;
        for (long j = 1; j <= i; j++) {
            if (i % j == 0) {
                divisors.push_back(j);
            }
        }
        if (divisors.size() == 2) {
            prime_numbers.push_back(i);
        }
    }
