    std::vector<long> largest_prime_number_digits;
    while (largest_prime_number != 0) {
        int digit = largest_prime_number % 10;
        largest_prime_number_digits.push_back(digit);
        largest_prime_number /= 10;
    }
    long sum = 0;
    for (auto i : largest_prime_number_digits) {
        sum += i;
    }
    return sum;
}

