vector<int> count_up_to(int n){
    std::vector<long> res;
	if (n < 2) {
		return res;
	}
	for (long i = 2; i < n; i++) {
		bool isPrime = true;
		for (long j = 2; j < i; j++) {
			if (i % j == 0) {
				isPrime = false;
				break;
			}
		}
		if (isPrime) {
			res.push_back(i);
		}
	}
	return res;
}

