    for(int i=0; i<nums.size(); i++){
        temp = nums[i];
        sum = 0;
        if(temp<0){
            temp = temp*(-1);
        }
        while(temp!=0){
            sum = sum + temp%10;
            temp = temp/10;
        }
        values.push_back(sum);
    }
    std::vector<long> original = nums;
    int minIndex{}, minValue{};
    while(values.size()!=0){
        minValue = values[0];
        minIndex = 0;
        for(int i=0; i<values.size(); i++){
            if(values[i]<minValue){
                minValue = values[i];
                minIndex = i;
            }
        }
        for(int i=0; i<original.size(); i++){
            if(original[i]==nums[minIndex]){
                result.push_back(original[i]);
                original.erase(original.begin()+i);
                nums.erase(nums.begin()+minIndex);
                values.erase(values.begin()+minIndex);
                break;
            }
        }
    }
    return result;
}

