#include<math.h>
#include<string>
#include<algorithm>
using namespace std;
#include<stdlib.h>
string encode(string message){
    // check message is valid
    if (message.empty()) {
        return message;
    }
    std::string encoded;
    std::vector<char> vowels = {'a', 'e', 'i', 'o', 'u'};
    for (char c : message) {
        // convert capital letters to lowercase
        char lower = std::tolower(c);
        // if it's a vowel, replace with it's replacement
        auto it = std::find(vowels.begin(), vowels.end(), lower);
        if (it != vowels.end()) {
            int index = std::distance(vowels.begin(), it);
            char next_vowel = vowels[(index + 2) % vowels.size()];
            encoded += next_vowel;
        } else {
            // otherwise just swap case
            encoded += std::isupper(c) ? std::tolower(c) : std::toupper(c);
        }
    }
    return encoded;
}

