#include<stdio.h>
#include<math.h>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int car_race_collision(int n){
    assert(n >= 1);
    // pre: n >= 1
    // post: We return the number of collisions.
    if (n==1) return 0;
    return n*n-n;
    // We'll develop a formal inductive proof for this in the future.
    // But for now, we'll do a heuristic argument.
    // Think of the number of cars as n.  Each car on the left moves
    // forward, one-by-one, colliding with all n cars on the right.
    // In total, there are n collisions, the first car on the left
    // collides with n cars on the right, then the second car on the left
    // collides with n-1 cars on the right, etc.
    // This is a geometric series with sum n(n+1)/2, or (n^2+n)/2.
    // But we counted each collision twice, so the answer is (n^2+n)/2 - n = (n^2-n)/2.
}

