#include<stdio.h>
#include<math.h>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int car_race_collision(int n){
    int nb_collision = 0;
    std::vector<bool> visited(n);
    for (long i = 0; i < n; i++) {
        long actual_car = i;
        while (actual_car < n) {
            long next_car = (actual_car + n) / 2;
            if (next_car == actual_car) break;
            if (visited[next_car]) break;
            actual_car = next_car;
            visited[actual_car] = true;
            nb_collision++;
        }
    }
    return nb_collision;
}

