#include<stdlib.h>
string circular_shift(int x,int shift){
    int num_digits = std::floor(std::log10(x)) + 1;
    if (shift > num_digits) {
        std::string s = std::to_string(x);
        std::reverse(s.begin(), s.end());
        return s;
    } else {
        long power = static_cast<long>(std::pow(10, shift));
        long div = x / power;
        long rem = x % power;
        return std::to_string(rem) + std::to_string(div);
    }
}

