#include<stdio.h>
#include<math.h>
#include<string>
using namespace std;
#include<algorithm>
#include<stdlib.h>
string circular_shift(int x,int shift){
    // Compute the length of the string needed to store the integer digits.
	long len = log10(x) + 1;
	// Extract each digit of the integer x by repeatedly dividing by 10 and
	// using the remainder as the next digit.
	std::string s;
	for (long i = 0; i < len; i++) {
		long x_digit = x % 10;
		s += std::to_string(x_digit);
		x /= 10;
	}
	// If the shift is greater than the number of digits, reverse the digits.
	if (shift > len) {
		std::reverse(s.begin(), s.end());
	}
	// Otherwise, circular shift the digits right.
	else {
		// Insert the digits at the end of the string into the beginning.
		std::rotate(s.begin(), s.begin() + len - shift, s.end());
	}
	return s;
}

