    std::vector<std::string> planets = {"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"};
    auto first = mapping.find(planet1);
    auto second = mapping.find(planet2);
    if (first == mapping.end() || second == mapping.end()) {
        return std::make_tuple();
    }
    std::tuple<std::string, > ans;
    if (first->second > second->second) {
        for (int i = second->second; i < first->second; i++) {
            std::get<0>(ans) = planets[i - 1];
        }
    } else {
        for (int i = first->second; i < second->second; i++) {
            std::get<0>(ans) = planets[i - 1];
        }
    }
    return ans;
}

