vector<int> parse_nested_parens(string paren_string){
    std::vector<long> nested_list;
    std::stringstream input_stream(paren_string);
    std::string paren_stream;
    while(std::getline(input_stream, paren_stream, ' ')) {
        std::stack<char> paren_stack;
        long max_depth = 0;
        for(long i = 0; i < paren_stream.size(); i++) {
            if(paren_stream[i] == '(') {
                paren_stack.push(paren_stream[i]);
                max_depth = std::max(max_depth, (long)paren_stack.size());
            }
            else if(paren_stream[i] == ')') {
                paren_stack.pop();
            }
        }
        nested_list.push_back(max_depth);
    }
    return nested_list;
}

