    int k = i + 1;
    // 3.3 let j = l.size() - 1
    int j = l.size() - 1;
    // 3.4 while k < j:
    while (k < j) {
      // 3.4.1 compute the sum of l[i], l[j], and l[k]
      long sum = l[i] + l[j] + l[k];
      // 3.4.2 if the sum is equal to zero, return True
      if (sum == 0) {
        return true;
      }
      // 3.4.3 if the sum is smaller than zero, increment k
      if (sum < 0) {
        k += 1;
      }
      // 3.4.4 if the sum is greater than zero, decrement j
      if (sum > 0) {
        j -= 1;
      }
    }
  }
