#include<vector>
#include<string>
using namespace std;
#include<algorithm>
#include<stdlib.h>
int do_algebra(vector<string> operato, vector<int> operand){
    // Write your code here
    stack<long>stk;
    stk.push(operand[0]);
    for(int i=0;i<_operator_.size();i++){
        char op = _operator_[i][0];
        if(op=='+')
            stk.push(operand[i+1]);
        else if(op=='-')
            stk.push(-operand[i+1]);
        else if(op=='*'){
            long val = stk.top();
            stk.pop();
            stk.push(val*operand[i+1]);
        }
        else if(op=='/'){
            long val = stk.top();
            stk.pop();
            stk.push(val/operand[i+1]);
        }
        else if(op=='^'){
            long val = stk.top();
            stk.pop();
            stk.push(pow(val,operand[i+1]));
        }
    }
    long ans = 0;
    while(!stk.empty()){
        ans+=stk.top();
        stk.pop();
    }
    return ans;
}

