    return 0;
  }
  if (n == 2) {
    return 1;
  }
  long m = n - 3;
  long first_fib = 0;
  long second_fib = 1;
  long current_fib = 1;
  long sum = 0;
  while (m >= 0) {
    m--;
    sum += first_fib;
    first_fib = second_fib;
    second_fib = current_fib;
    current_fib = first_fib + second_fib;
  }
  return sum + current_fib;
}

