#include<math.h>
#include<vector>
#include<algorithm>
using namespace std;
#include<stdlib.h>
vector<int> minPath(vector<vector<int>> grid, int k){
    int n = grid.size();
    long start = grid[0][0];
    std::priority_queue<std::vector<long>, std::vector<std::vector<long>>, std::greater<std::vector<long>>> q;
    std::set<long> visited;
    std::vector<long> result;
    std::vector<std::vector<long>> offsets = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    std::vector<long> elem = {start, 0, 0, 0};
    q.push(elem);
    while (!q.empty()) {
        std::vector<long> curr = q.top();
        q.pop();
        long val = curr[0];
        long len = curr[1];
        long x = curr[2];
        long y = curr[3];
        if (len == k) {
            result.push_back(val);
            break;
        }
        for (int i = 0; i < offsets.size(); i++) {
            long next_x = x + offsets[i][0];
            long next_y = y + offsets[i][1];
            if (next_x >= 0 && next_x < n && next_y >= 0 && next_y < n) {
                long next_val = grid[next_x][next_y];
                if (visited.find(next_val) == visited.end()) {
                    std::vector<long> next_elem = {next_val, len + 1, next_x, next_y};
                    q.push(next_elem);
                    visited.insert(next_val);
                }
            }
        }
    }
    return result;
}

