    std::vector<long> path;
    // For all k, we need to start at the 1.
    path.push_back(1);
    if (k == 1) {
        return path;
    }
    for (int i = 0; i < k - 1; i++) {
        // Find the position of the last value in the path
        int row = 0;
        int col = 0;
        for (int r = 0; r < grid.size(); r++) {
            for (int c = 0; c < grid[0].size(); c++) {
                if (grid[r][c] == path.back()) {
                    row = r;
                    col = c;
                }
            }
        }
        // Pick a neighbor to go to.
        if (row - 1 >= 0 && grid[row - 1][col] == grid[row][col] + 1) {
            path.push_back(grid[row - 1][col]);
        } else if (row + 1 < grid.size() && grid[row + 1][col] == grid[row][col] + 1) {
            path.push_back(grid[row + 1][col]);
        } else if (col - 1 >= 0 && grid[row][col - 1] == grid[row][col] + 1) {
            path.push_back(grid[row][col - 1]);
        } else if (col + 1 < grid[0].size() && grid[row][col + 1] == grid[row][col] + 1) {
            path.push_back(grid[row][col + 1]);
        }
    }
    return path;
}

