  std::unordered_map<long, bool> encountered_elements;
  std::vector<long> solution;
  for (long n : numbers) {
    // if the value has been encountered in the hashmap, don't include it in
    // solution.
    if (encountered_elements.find(n) == encountered_elements.end()) {
      encountered_elements[n] = true;
      solution.push_back(n);
    }
  }
  return solution;
}

