    std::stringstream ss(test);
    std::string s_arr[test.length()];
    int j = 0;
    if(test.length() == 0) {
        return ret;
    }
    for(int i = 0; i < test.length(); i++) {
        if(test[i] == ' ') {
            flag = 1;
        }
    }
    if(flag == 0) {
        for(int i = 0; i < test.length(); i++) {
            if(i == 0) {
                ret.insert(std::pair<std::string, long>(test.substr(i, 1), test.length()));
            }
            else {
                ret.insert(std::pair<std::string, long>(test.substr(i, 1), 0));
            }
        }
        return ret;
    }
    while(ss >> temp) {
        s_arr[j] = temp;
        j++;
    }
    std::sort(s_arr, s_arr + j);
    for(int i = 0; i < j; i++) {
        it = ret.find(s_arr[i]);
        if(it == ret.end()) {
            ret.insert(std::pair<std::string, long>(s_arr[i], 1));
        }
        else {
            it->second++;
        }
    }
    return ret;
}

