#include<algorithm>
#include<math.h>
#include<stdlib.h>
vector<string> filter_by_substring(vector<string> strings, string substring){
    std::vector<std::string> filtered_strings;
  for (int i = 0; i < strings.size(); i++) {
    bool contain_substring = false;
    for (int j = 0; j < strings[i].size(); j++) {
      if (strings[i][j] == substring[0]) {
        int cnt = 0;
        for (int k = j; k < strings[i].size(); k++) {
          if (cnt == substring.size()) {
            contain_substring = true;
            break;
          }
          if (strings[i][k] == substring[cnt]) {
            cnt++;
          } else {
            break;
          }
        }
      }
    }
    if (contain_substring) {
      filtered_strings.push_back(strings[i]);
    }
  }
  return filtered_strings;
}

